38	/* Tracks which value pointers the tree has actually freed, so insert tests
39	 * can tell "old value freed on overwrite" apart from "value untouched on
40	 * allocation failure" instead of just trusting the return code. */
41	#define MAX_FREED 16
42	static void *freed_values[MAX_FREED];
43	static int freed_count;
44	
45	static void reset_tracking(void)
46	{
47	    freed_count = 0;
48	}
49	
50	static void track_free(void *value)
51	{
52	    assert(freed_count < MAX_FREED);
53	    freed_values[freed_count++] = value;
54	    free(value);
55	}
56	
57	static int was_freed(void *value)
58	{
59	    for (int i = 0; i < freed_count; i++)
60	        if (freed_values[i] == value)
61	            return 1;
62	    return 0;
63	}
64	
65	/* Distinguishes "freed once" from "freed twice" (a real double free), which
66	 * was_freed's plain membership check can't tell apart. */
67	static int free_occurrences(void *value)
68	{
69	    int n = 0;
70	    for (int i = 0; i < freed_count; i++)
71	        if (freed_values[i] == value)
72	            n++;
73	    return n;
74	}
75	
76	/* Scoped variants of was_freed/free_occurrences: only consider frees
77	 * recorded at or after `since` (a freed_count high-water mark taken right
78	 * before the value under test was allocated). Needed because glibc's
79	 * tcache commonly hands a just-freed same-size chunk back to the very next
80	 * malloc -- an unscoped scan would false-positive on a *stale* entry for a
81	 * previous, unrelated allocation that happened to reuse the same address. */
82	static int was_freed_since(void *value, int since)
83	{
84	    for (int i = since; i < freed_count; i++)
85	        if (freed_values[i] == value)
86	            return 1;
87	    return 0;
88	}
89	
90	static int free_occurrences_since(void *value, int since)
91	{
92	    int n = 0;
93	    for (int i = since; i < freed_count; i++)
94	        if (freed_values[i] == value)
95	            n++;
96	    return n;
97	}
