99	#define MAX_COLLECT 16
100	typedef struct {
101	    const char *keys[MAX_COLLECT];
102	    void *values[MAX_COLLECT];
103	    int n;
104	} collect_ctx_t;
105	
106	static void collect_cb(const char *key, void *value, void *ctx)
107	{
108	    collect_ctx_t *c = ctx;
109	    assert(c->n < MAX_COLLECT);
110	    c->keys[c->n] = key;
111	    c->values[c->n] = value;
112	    c->n++;
113	}
114	
115	typedef struct {
116	    const char *name;
117	    rb_value_free_fn value_free;
118	    int fail_at;          /* 0 = no injected malloc failure */
119	    int expect_nonnull;
120	    int expect_free_count; /* rb_free calls during the faulted create; -1 = n/a */
121	} create_case_t;
122	
123	/* Baseline success (with/without value_free), and injected failure on
124	 * each of rb_create's two allocations (the struct, then the nil
125	 * sentinel). Each row that returns non-NULL also exercises
126	 * destroy-after-success being crash-free and memcheck-clean, and now
127	 * checks rb_validate and that value_free is never spuriously invoked
128	 * on an empty tree.
129	 *
130	 * fail_at assumes rb_create makes exactly two rb_malloc calls, in this
131	 * order: the tree struct, then the nil sentinel. If that allocation
132	 * strategy changes, these cases will fail loudly via expect_nonnull
133	 * rather than silently no-op. expect_free_count values: fail_at=1
134	 * fails before anything is allocated, so cleanup frees nothing (0);
135	 * fail_at=2 fails after the tree struct succeeds, so cleanup frees
136	 * exactly that one allocation (1). */
137	static const create_case_t create_cases[] = {
138	    { "create_null_value_free",    NULL,          0, 1, -1 },
139	    { "create_nonnull_value_free", counting_free, 0, 1, -1 },
140	    { "create_fail_first_alloc",   NULL,          1, 0,  0 },
141	    { "create_fail_second_alloc",  NULL,          2, 0,  1 },
142	};
143	
144	static void test_rb_create(void)
145	{
146	    size_t n = sizeof create_cases / sizeof create_cases[0];
147	    /* invariant: each iteration leaves no allocation armed and no tree
148	     * leaked, regardless of whether rb_create succeeded. */
149	    for (size_t i = 0; i < n; i++) {
150	        const create_case_t *c = &create_cases[i];
151	
152	        if (c->fail_at)
153	            fault_malloc_arm(c->fail_at);
154	        rbtree_t *t = rb_create(c->value_free);
155	        if (c->fail_at) {
156	            assert(fault_malloc_free_count() == c->expect_free_count);
157	            fault_malloc_disarm();
158	        }
159	
160	        assert((t != NULL) == c->expect_nonnull);
161	
162	        if (t) {
163	            assert(rb_size(t) == 0);
164	            assert(rb_validate(t) == 0);
165	            assert(rb_find(t, "probe") == NULL);
166	            int calls = 0;
167	            rb_foreach(t, count_cb, &calls);
168	            assert(calls == 0);
169	            value_free_calls = 0;
170	            rb_destroy(t);
171	            assert(value_free_calls == 0);
172	        }
173	        printf("ok - %s\n", c->name);
174	    }
175	
176	    /* Two live trees don't share hidden state. */
177	    {
178	        rbtree_t *a = rb_create(NULL);
179	        rbtree_t *b = rb_create(NULL);
180	        assert(a && b && a != b);
181	        assert(rb_size(a) == 0 && rb_size(b) == 0);
182	        assert(rb_validate(a) == 0 && rb_validate(b) == 0);
183	        rb_destroy(a);
184	        assert(rb_size(b) == 0);
185	        rb_destroy(b);
186	        printf("ok - create_independent_instances\n");
187	    }
188	
189	    /* rb_destroy is documented NULL-safe. */
190	    {
191	        rb_destroy(NULL);
192	        printf("ok - create_destroy_null_safe\n");
193	    }
194	}
