196	/* White-box fixture helper: builds one node directly (bypassing rb_insert)
197	 * so test_rb_validate can wire up structurally-valid-but-invariant-violating
198	 * trees that rb_insert itself should never be able to produce. */
199	static rbnode_t *mk_node(rbtree_t *t, const char *key, int color)
200	{
201	    rbnode_t *n = rb_malloc(sizeof *n);
202	    assert(n);
203	    n->key = rb_malloc(strlen(key) + 1);
204	    assert(n->key);
205	    memcpy(n->key, key, strlen(key) + 1);
206	    n->value = NULL;
207	    n->left = n->right = n->parent = t->nil;
208	    n->color = color;
209	    return n;
210	}
