212	/* Every mk_node-built fixture allocates exactly node_count node structs and
213	 * node_count key buffers; rb_destroy must free all of those plus nil and the
214	 * tree struct itself -- no more (a leak) and no less (an over-free, or nil
215	 * getting freed more than once if traversal doesn't stop at the sentinel). */
216	static void destroy_and_check_frees(rbtree_t *t, int node_count)
217	{
218	    fault_malloc_arm(0);          /* never fails; just resets the free counter */
219	    rb_destroy(t);
220	    assert(fault_malloc_free_count() == node_count * 2 + 2);
221	    fault_malloc_disarm();
222	}
