224	/* rb_validate must enforce four invariants: BST order, red implies black
225	 * children, equal black-height on every root-to-nil path, and the root is
226	 * black. Each case below isolates exactly one of those, and every violation
227	 * gets its left/right (or shallow/deep) mirror so an implementation that
228	 * only checks one side can't pass by accident. */
229	static void test_rb_validate(void)
230	{
231	    /* Cases 1-4: red-red violation (a red node with a red child), at each
232	     * combination of which side of the root the red parent is on and which
233	     * side of that parent the red child is on. Ordering is correct and both
234	     * root-to-nil paths carry the same black count in every case, so only
235	     * the red-red rule is broken. */
236	    {
237	        static const struct {
238	            const char *name;
239	            const char *parent_key;
240	            int parent_is_left;      /* parent is root's left (1) or right (0) child */
241	            const char *child_key;
242	            int child_is_left;       /* red child is parent's left (1) or right (0) child */
243	        } cases[] = {
244	            { "validate_red_red_LL", "d", 1, "b", 1 },
245	            { "validate_red_red_LR", "d", 1, "f", 0 },
246	            { "validate_red_red_RL", "t", 0, "r", 1 },
247	            { "validate_red_red_RR", "t", 0, "v", 0 },
248	        };
249	        for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
250	            rbtree_t *t = rb_create(NULL);
251	            assert(t);
252	
253	            rbnode_t *parent = mk_node(t, cases[i].parent_key, RB_RED);
254	            rbnode_t *child = mk_node(t, cases[i].child_key, RB_RED);
255	            child->parent = parent;
256	            if (cases[i].child_is_left)
257	                parent->left = child;
258	            else
259	                parent->right = child;
260	
261	            rbnode_t *root = mk_node(t, "m", RB_BLACK);
262	            root->parent = t->nil;
263	            if (cases[i].parent_is_left) {
264	                root->left = parent;
265	                root->right = t->nil;
266	            } else {
267	                root->right = parent;
268	                root->left = t->nil;
269	            }
270	            parent->parent = root;
271	            t->root = root;
272	            t->size = 3;
273	
274	            assert(rb_validate(t) != 0);
275	            destroy_and_check_frees(t, 3);
276	            printf("ok - %s\n", cases[i].name);
277	        }
278	    }
279	
280	    /* Cases 5-8: BST-order violation. The first two are immediate
281	     * parent/child inversions; the last two are deeper ancestor-bound
282	     * violations -- a node that's fine relative to its immediate parent but
283	     * violates a grandparent's bound, which a validator that only compares
284	     * a node to its direct parent (instead of threading a min/max bound)
285	     * would miss. All nodes BLACK so there's no red-red/black-height noise. */
286	    {
287	        rbtree_t *t = rb_create(NULL);
288	        assert(t);
289	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
290	        rbnode_t *left = mk_node(t, "z", RB_BLACK); /* should be < "m" */
291	        root->left = left;
292	        root->right = t->nil;
293	        root->parent = t->nil;
294	        left->parent = root;
295	        t->root = root;
296	        t->size = 2;
297	        assert(rb_validate(t) != 0);
298	        destroy_and_check_frees(t, 2);
299	        printf("ok - validate_bst_order_immediate_left_too_big\n");
300	    }
301	    {
302	        rbtree_t *t = rb_create(NULL);
303	        assert(t);
304	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
305	        rbnode_t *right = mk_node(t, "b", RB_BLACK); /* should be > "m" */
306	        root->right = right;
307	        root->left = t->nil;
308	        root->parent = t->nil;
309	        right->parent = root;
310	        t->root = root;
311	        t->size = 2;
312	        assert(rb_validate(t) != 0);
313	        destroy_and_check_frees(t, 2);
314	        printf("ok - validate_bst_order_immediate_right_too_small\n");
315	    }
316	    {
317	        rbtree_t *t = rb_create(NULL);
318	        assert(t);
319	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
320	        rbnode_t *left = mk_node(t, "d", RB_BLACK);       /* valid: "d" < "m" */
321	        rbnode_t *deep = mk_node(t, "x", RB_BLACK);       /* valid vs "d": "x" > "d" ... */
322	        left->right = deep;                               /* ...but "x" > "m" violates root's bound */
323	        left->left = t->nil;
324	        deep->left = deep->right = t->nil;
325	        root->left = left;
326	        root->right = t->nil;
327	        root->parent = t->nil;
328	        left->parent = root;
329	        deep->parent = left;
330	        t->root = root;
331	        t->size = 3;
332	        assert(rb_validate(t) != 0);
333	        destroy_and_check_frees(t, 3);
334	        printf("ok - validate_bst_order_deep_left_exceeds_root\n");
335	    }
336	    {
337	        rbtree_t *t = rb_create(NULL);
338	        assert(t);
339	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
340	        rbnode_t *right = mk_node(t, "t", RB_BLACK);      /* valid: "t" > "m" */
341	        rbnode_t *deep = mk_node(t, "c", RB_BLACK);       /* valid vs "t": "c" < "t" ... */
342	        right->left = deep;                                /* ...but "c" < "m" violates root's bound */
343	        right->right = t->nil;
344	        deep->left = deep->right = t->nil;
345	        root->right = right;
346	        root->left = t->nil;
347	        root->parent = t->nil;
348	        right->parent = root;
349	        deep->parent = right;
350	        t->root = root;
351	        t->size = 3;
352	        assert(rb_validate(t) != 0);
353	        destroy_and_check_frees(t, 3);
354	        printf("ok - validate_bst_order_deep_right_below_root\n");
355	    }
356	
357	    /* Cases 9-10: black-height mismatch. All nodes BLACK, correct BST
358	     * order, differing only in which side carries an extra black node. */
359	    {
360	        rbtree_t *t = rb_create(NULL);
361	        assert(t);
362	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
363	        rbnode_t *left = mk_node(t, "b", RB_BLACK);
364	        left->left = left->right = t->nil;
365	        root->left = left;
366	        root->right = t->nil; /* one black shorter than the left path */
367	        root->parent = t->nil;
368	        left->parent = root;
369	        t->root = root;
370	        t->size = 2;
371	        assert(rb_validate(t) != 0);
372	        destroy_and_check_frees(t, 2);
373	        printf("ok - validate_black_height_left_heavy\n");
374	    }
375	    {
376	        rbtree_t *t = rb_create(NULL);
377	        assert(t);
378	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
379	        rbnode_t *right = mk_node(t, "v", RB_BLACK);
380	        right->left = right->right = t->nil;
381	        root->right = right;
382	        root->left = t->nil; /* one black shorter than the right path */
383	        root->parent = t->nil;
384	        right->parent = root;
385	        t->root = root;
386	        t->size = 2;
387	        assert(rb_validate(t) != 0);
388	        destroy_and_check_frees(t, 2);
389	        printf("ok - validate_black_height_right_heavy\n");
390	    }
391	
392	    /* Case 11: root color. A single red root is valid BST order (only one
393	     * node), has no red-red violation (no children to conflict with), and
394	     * has equal (zero-length) black-height on both sides -- the only broken
395	     * rule is that the root itself must be black. */
396	    {
397	        rbtree_t *t = rb_create(NULL);
398	        assert(t);
399	        rbnode_t *root = mk_node(t, "m", RB_RED);
400	        root->left = root->right = t->nil;
401	        root->parent = t->nil;
402	        t->root = root;
403	        t->size = 1;
404	        assert(rb_validate(t) != 0);
405	        destroy_and_check_frees(t, 1);
406	        printf("ok - validate_root_must_be_black\n");
407	    }
408	}
